INSERT INTO ref_sig_abilities (key, name, description, career_key, dataset_source, is_retired) VALUES ('ALWAYSGETMYMARK', 'Always Get My Mark', 'Once per game session, the character may choose a minion NPC to be her mark. She must know this NPC''s identity and basic personal information (or have another lead of comparable quality, per the GM''s discretion), and must know that the NPC is on the same planet. She spends 2 Destiny Points, and makes a [B]Hard ([DI][DI][DI]) Streetwise check[b]. If she succeeds, the character tracks down the chosen mark, and a new enounter begins as the character reaches the mark''s location.
INSERT INTO ref_sig_abilities (key, name, description, career_key, dataset_source, is_retired) VALUES ('COUNTERESPIONAGE', 'Counterespionage', 'Spies know foiling the plots of enemy agents is always paramount, and devote much preparation to thwarting these schemes. This might be done via hiding weapons in a meeting place, ensuring "innocent bystanders" are in fact armed backup, or other cunning and clever ploys. The more agents are aware of their opposite numbers and enemy tactics, the better they can achieve their goals. Counterespionage ideally leads to the grand prize: turning an enemy into a valuable double agent.
INSERT INTO ref_sig_abilities (key, name, description, career_key, dataset_source, is_retired) VALUES ('DEADLYREP', 'Deadly Reputation', 'Many accomplished Warriors reach a point in their life when their reputation precedes them. Whether famous or infamous, a reputation as a fighter and killer carries with it a warning and threat of danger. Such a reputation may color all of the Warrior''s interactions to some degree.
INSERT INTO ref_sig_abilities (key, name, description, career_key, dataset_source, is_retired) VALUES ('DIPLOMATICSOL', 'Diplomatic Solution', 'The ability to bring belligerent parties to the negotiating table is no task for the fainthearted, and it is absolutely indispensable to the work of Diplomats. This is especially true during the chaos of the Galactic Civil War, for agents of the Rebel Alliance must deal with all manner of dangerous characters. Whether with a warm smile, a stern command, or a withering glare, a Diplomat who has mastered this ability can make the most callous soldier of fortune or bounty hunter balk and holster his blaster.
INSERT INTO ref_sig_abilities (key, name, description, career_key, dataset_source, is_retired) VALUES ('FATDUEL', 'Fated Duel', 'Many of the most iconic scenes in stories of heroism and sacrifice begin with two combatants drawing (or igniting) their blades to fight a duel to the death. This signature ability allows a guardian to force a single foe into a duel, preventing both participants from attacking others for several rounds. Guardians can use this signature ability to give allies a chance to recover and regroup, and to distract a powerful foe while comrades clear out weaker enemies, or even to stave off a single deadly combatant while allies make their escape. [P]Characters who have  mastered this signature ability can provide substantial boons to their allies while they fight the duel, giving them the best chance to complete important tasks without interruption. Of course, any use of this signature ability represents a considerable risk on the part of the Guardian, for it means bearing the entire burden of fighting a particular foe, if only for a short time. Such duels have been the finest moments of many Guardians, but also their last.
INSERT INTO ref_sig_abilities (key, name, description, career_key, dataset_source, is_retired) VALUES ('INSIGHTREVEL', 'Insightful Revelation', 'Many fringers may scoff at the highly educated individual, mocking him as an ivory tower academic with no experience in the real world. What most people don''t realize is just how effective the academic can be when he applies his formidable intellect and lengthy education to the task at hand. When confronted with an impossible quandary, the Colonist can use his vast store of knowledge to analyze the problem and arrive at a solution nobody else could have even begun to figure out.
INSERT INTO ref_sig_abilities (key, name, description, career_key, dataset_source, is_retired) VALUES ('INVENTIVECREATION', 'Inventive Creation', 'On the fringes of the galaxy, technical self-reliance often means the difference between life and death. While Technicians in the Core Worlds might not need to be able to whip up functional devices out of fragmented scraps and frayed wires, someone in the Outer Rim rarely has the luxury of pristine tools, sufficient equpment, or even basic supplies. But necessity, they say, is the mother of invention. Outer Rim Technicians often display incredible resourcefulness, scrapping together complex devices from mundane materials.
INSERT INTO ref_sig_abilities (key, name, description, career_key, dataset_source, is_retired) VALUES ('LOS', 'Last One Standing', 'Sometimes, when he has no other choice a character must defy the odds and fight against overwhelming opposition. This action seems suicidal. However, the very best can walk through the fire of overwhelming odds, defeat their enemies, and emerge bloody but victorious.
INSERT INTO ref_sig_abilities (key, name, description, career_key, dataset_source, is_retired) VALUES ('MUCHTOLEARN', 'Much to Learn', 'In an era when the Jedi are all but extinct, passing on the scattered remnants of their teachings has become a vital task. At the same time, those who teach must also expect to be on the front lines against the forces that would snuff out the light of the Jedi forever. Some of these dedicated individuals see the chance to turn this struggle into a classroom. They adopt charges and apprentices, then carry on instruction even as both master and student continue the fight for survival. For such characters, every conflict is a lesson waiting to be taught.
INSERT INTO ref_sig_abilities (key, name, description, career_key, dataset_source, is_retired) VALUES ('MYCITY', 'My City', 'Once per game session when in a chosen urban setting, the character may spend 2 Destiny Points and make a [B]Hard ([DI][DI][DI]) Knowledge (Core Worlds)[b] or [B]Knowledge (Outer Rim) check[b] (depending on the location). If successful, for the remainder of the game session, the character may suffer 2 strain to recall or learn the location of any individual, group, or establishment within that city, along with any relevant information such as reputation, rumored or open ties to the Empire or Rebellion, criminal nature (if any).', 'SENTINEL', 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_sig_abilities (key, name, description, career_key, dataset_source, is_retired) VALUES ('NARROWESCAPE', 'Narrow Escape', 'Whether a smuggling deal has gone south or the authorities see through the ship''s fake transponder code, Smugglers frequently find themselves in a position where they need to make a getaway—and fast. Besides, what good is a reward if nobody gets to spend it?
INSERT INTO ref_sig_abilities (key, name, description, career_key, dataset_source, is_retired) VALUES ('PEERLESSINTERCEP', 'Peerless Interception', 'Once per session as an out-of-turn incidental, the character may spend 2 Destiny Points to activate Peerless Interception. Until the end of the character''s second turn after activating Peerless Interception, when they use Parry or Reflect to reduce the damage of a hit, they reduce the damage by an additional amount equal to their current Force rating.', 'JEDI', 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_sig_abilities (key, name, description, career_key, dataset_source, is_retired) VALUES ('PROPHECY', 'Prophecy', 'The future is always in motion, and trying to predict it through the Force is a tricky and even dangerous endeavor. Even if one can sift through the shifting strands of fate and pick out the future most likely to occur, trying to bring about or stop that future may cause one to take actions that end up having the opposite effect. Nevertheless, many Force users delve into the dangerous art of prophecy, because if they succeed, the rewards can be great beyond measure.
INSERT INTO ref_sig_abilities (key, name, description, career_key, dataset_source, is_retired) VALUES ('ROUSOR', 'Rousing Oratory', 'Many in the Empire think that a commander is defined
INSERT INTO ref_sig_abilities (key, name, description, career_key, dataset_source, is_retired) VALUES ('SHADOWLORD', 'Shadow Lord', 'Syndicates are enterprises, which means they have two things: people to do the work, and the bosses who tell them what to do. When a character reaches a certain level of prestige, importance, and resources within a syndicate, they gain access to expendable underlings, who are at a Shadow Lord''s beck and call, prepared to do what it takes to earn the favor of their superior.
INSERT INTO ref_sig_abilities (key, name, description, career_key, dataset_source, is_retired) VALUES ('SUDDENDISC', 'Sudden Discovery', 'Plying the endless worlds of the galaxy leads Explorers to master many different skills, not the least of which is the uncanny ability to keep their bearing no matter where they find themselves. A veteran spacer may be able to ascertain his position in the galaxy by simply staring out of the cockpit, while an experienced scout may be able to find his way out of a completely unknown alien wilderness solely through instinct and past experience. 
INSERT INTO ref_sig_abilities (key, name, description, career_key, dataset_source, is_retired) VALUES ('BIGGERTHEYARE', 'The Bigger They Are...', 'Once per game session as an action, the character may spend 2 Destiny Points, nominate one vehicle, starship, or living creature of silhouette 2 or smaller that he can see, and make a [B]Hard ([DI][DI][DI]) Knowledge (Warfare) check[b]. If he succeeds, for the next 3 rounds, he and each other friendly character within medium range of him ignore the target''s armor (or soak, if it is a living creature) when inflicting damage on the target with non-vehicle/starship weapons.', 'SOLDIER', 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_sig_abilities (key, name, description, career_key, dataset_source, is_retired) VALUES ('HARDERTHEYFALL', 'The Harder They Fall', 'While it might be loathsome or insulting to their professional pride, all Alliance Engineers realize they are fighting in a war, and that a great part of war involves destruction. This includes the destruction of buildings, fortifications, ships, and droids-the very things they work so hard to create and maintain. Their expertise in these areas, though, makes for excellent combat abilities. Drawing on their know ledge of technological vulnerabilities. Engineers can help ensure maximum efficiencies in attacks they and their comrades make.
INSERT INTO ref_sig_abilities (key, name, description, career_key, dataset_source, is_retired) VALUES ('THISONEISMINE', 'This One is Mine', 'Amidst the pandemonium of battles involving hundreds of starships and vehicles, pilots must ignore the chaos around them and focus on individual enemy targets to prioritize. Ace characters have become masters of this. When they focus on a target, all else seems to disappear around them as they stalk their prey. And in turn, as an Ace begins the attack, his target is forced to focus all its attention on staying alive. As the two combatants fight, they weave through the ongoing battle, ignored by all others as they duel for their lives.
INSERT INTO ref_sig_abilities (key, name, description, career_key, dataset_source, is_retired) VALUES ('UNEXPECTEDDEMISE', 'Unexpected Demise', 'Once per session, as an action, the character may spend 2 Destiny Points and make a [B]Hard ([DI][DI][DI]) Perception check[b]. If successful, for the next two rounds the character may spend one maneuver to add on automatic [TR] to his next combat check made in that turn. In addition, for the next two rounds, when the character inflicts a Critical Injury on a rivel NPC, the target is immediately incapacitated in the same way as a minion NPC would be (see page 400 of the [B]Force and Destiny[b] Core Rulebook).', 'SEEKER', 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_sig_abilities (key, name, description, career_key, dataset_source, is_retired) VALUES ('UNMATCHEDAMB', 'Unmatched Ambition', 'Only one word can describe those who dedicate their lives to criminal pursuits: ambitious. If they aren''t in a constant struggle to realize their own rags to riches story, they are working to multiply the multitudes of their wealth and influence. Be it by cold ruthlessness, an expression of skill, or through sheer force of will, a career Syndicate won''t allow anything to stand between them and their goals.
INSERT INTO ref_sig_abilities (key, name, description, career_key, dataset_source, is_retired) VALUES ('UNMATCHEDAUTH', 'Unmatched Authority', 'Few realize the true strain of command. Balancing
INSERT INTO ref_sig_abilities (key, name, description, career_key, dataset_source, is_retired) VALUES ('UNMATCHEDCALIBRATION', 'Unmatched Calibration', 'The character has the capacity to act with incredible accuracy and finesse, reacting dispassionately and deftly to problems and capitalizing on oppurtunites as they arise. Steady hands, sharp wits, and calm nerves developed while working on colatile engines, delicate instruments or ever-shifting Slicers'' code give the Technician an edge in any situation. After all, composure and logical analysis are applicable to nearly any activity, whether that is defusing a bomb, calling up schematics in a hurry, or even participating in a firefight. Thus, even when facing novel, problems, the character can act efficiently and decisively, analyzing and dispatching the thorniest problems with practiced ease. To this technician, every problem is a puzzle to be solved, and there is always an optimal move to advance towards the answer.
INSERT INTO ref_sig_abilities (key, name, description, career_key, dataset_source, is_retired) VALUES ('UNMATCHEDCOURAGE', 'Unmatched Courage', 'Once per game session, as an out of turn incidental, the character may spend 2 Destiny Points to ignore the effects of all Critical Injuries for 2 rounds (he still suffers these Critical Injuries, even though he ignores their effects). When this effect ends at the end of the third round, he immediately suffers the effects of all Critical Injuries he is suffering as normal.', 'SOLDIER', 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_sig_abilities (key, name, description, career_key, dataset_source, is_retired) VALUES ('UNMATCHEDDESTINY', 'Unmatched Destiny', 'The most powerful Mystics have an unmatched mastery of the Force. Their connection is so deep and so instinctive that they can call upon it at will. However, this powerful connection has a cost, and these Mystics risk opening themselves to the dark side of the Force.
INSERT INTO ref_sig_abilities (key, name, description, career_key, dataset_source, is_retired) VALUES ('UNMATCHEDDEVASTATION', 'Unmatched Devastation', 'Once per game session, after performing a combat check, the character may spend 2 Destiny Points to perform one additional combat check against the same target as an incidental.
INSERT INTO ref_sig_abilities (key, name, description, career_key, dataset_source, is_retired) VALUES ('UNMATCHEXPERT', 'Unmatched Expertise', 'A combination of education and hard-earned life experiences can make Colonists far more capable individuals than they appear. When the time is right, they can put their vast experience to good use, making challenging tasks look easy, and the impossible merely difficult. 
INSERT INTO ref_sig_abilities (key, name, description, career_key, dataset_source, is_retired) VALUES ('UNMATCHEDFEROCITY', 'Unmatched Ferocity', 'All Warriors walk a fine line between ferocity and control. Some Warriors, particularly with the aid of the Force, can unleash a barrage of blows on a foe, overwhelming their defenses and ending a confrontation in one dramatic onslaught. Even when tempered with skill and control, such an assault draws on anger or other negative emotions, which might overtake the Warrior.
INSERT INTO ref_sig_abilities (key, name, description, career_key, dataset_source, is_retired) VALUES ('UNMATCHEDFORTUNE', 'Unmatched Fortune', 'Smugglers learn early on to be self-reliant and sure of themselves. It isn''t enough to hope things will work out or believe in some hokey religion—they have to take luck into their own hands if they want to keep flying, much less make a credit or two.
INSERT INTO ref_sig_abilities (key, name, description, career_key, dataset_source, is_retired) VALUES ('UNMATCHHERO', 'Unmatched Heroism', 'The act of sheltering allies is frequently a literal one for Guardians. This signature ability allows Guardians to intercept attacks meant for friends, taking mighty strikes in their allies'' place. Since Guardians often have the means of mitigating incoming attacks, from deft sword skills to resilient armor to Force-enhanced toughness, they can often resist strikes that would incapacitate or even slay their comrades. Some Guardians can even capitalize on being hit, launching counterstrikes or otherwise smiting foes who strike at them. Armed with this signature ability, a Guardian can safeguard a whole party against numerous foes for several rounds.
INSERT INTO ref_sig_abilities (key, name, description, career_key, dataset_source, is_retired) VALUES ('UNMATCHEDINGEN', 'Unmatched Ingenuity', 'There are few things Engineers love more than to tinker with their equipment Prior to going in to battle (or even in the midst of it, given the opportunity), any Engineers worth their hydrospanners will rebuild slugthrower feeds, reposition missile detonator sensors, or reroute power ducting in blasters. In the minds of Engineers. there is nothing that cannot be improved, and using weaponry as it arrived from the logistics supply sources is a sign of laziness or lack of skill. It is a point of pride for them to always add some ingenious improvement to not only their own weapons, but the weapons of their fellow Alliance soldiers.
INSERT INTO ref_sig_abilities (key, name, description, career_key, dataset_source, is_retired) VALUES ('UNINS', 'Unmatched Insight', 'People are a politician''s business, so understanding other sentient beings is absolutely critical to a representative''s job. Many veteran Diplomats develop an astounding ability to read others with only a moments glance, discerning precisely what to tell a constituent to win his support or which question to ask a fellow politician to undermine his authority.
INSERT INTO ref_sig_abilities (key, name, description, career_key, dataset_source, is_retired) VALUES ('UNMOB', 'Unmatched Mobility', 'Agile and talented, Explorer characters often survive and thrive among the dangers of the galaxy through the use of speed and mobility. A seasoned Explorer can focus under pressure, using adrenaline and training to move around and complete tasks faster than those around him. Some use this ability to evade danger, keeping themselves out of harm''s way. Others use it to gain an edge against their foes, outmaneuvering them in battle.
INSERT INTO ref_sig_abilities (key, name, description, career_key, dataset_source, is_retired) VALUES ('UNMATCHEDNEGOTIATIONS', 'Unmatched Negotiations', 'The best negotiatiors do not just see any conflict as a potential negotiated settlement waiting to be resolved; they also have the foresight to anticipate any potential pitfalls, mistakes, or points of contention before the negotiations even begin. When they sit down at the bargaining table, these negotiators ensure that whether the negotiations succeed or fail, everyone involved (especially the negotiator!) avoids any unintended slights, insults, or unfortunate verbal mistakes.
INSERT INTO ref_sig_abilities (key, name, description, career_key, dataset_source, is_retired) VALUES ('UNPROT', 'Unmatched Protection', 'Some of the toughest sentients in the galaxy are Hired Guns. A lifetime of conflict leaves them covered in scars from countless wounds. However, this also leaves them as tough and resilient as durasteel.
INSERT INTO ref_sig_abilities (key, name, description, career_key, dataset_source, is_retired) VALUES ('UNMATCHEDPURSUIT', 'Unmatched Pursuit', 'Once per game session, as an out of turn incidental, the character may spend 2 Destiny Points and designate one enemy character or vehicle within medium range (either personal or planetary scale) as his quarry. For the next 3 rounds if the designated target would successfully elude his pursuit, the character may voluntarily suffer 2 strain to keep pace, preventing the target from escaping him.', 'SEEKER', 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_sig_abilities (key, name, description, career_key, dataset_source, is_retired) VALUES ('UNMATCHEDSURV', 'Unmatched Survivability', '[H4]Ace Signature Ability: Unmatched Survivability[h4]
INSERT INTO ref_sig_abilities (key, name, description, career_key, dataset_source, is_retired) VALUES ('UNMATCHEDTEAMWORK', 'Unmatched Teamwork', '[H4]Unmatched Teamwork[h4]
INSERT INTO ref_sig_abilities (key, name, description, career_key, dataset_source, is_retired) VALUES ('UNMATCHEDTRADECRAFT', 'Unmatched Tradecraft', 'The essence of tradecraft is that of perfect deception. The greatest of espionage agents turn adopting false identities, spouting convincing cover stories at a moment''s notice, moving across secured areas without detection, picking locks, and other vital skills into art forms. They are not simply skilled at performing deception—to them, deception is an almost reflexive action, seamlessly brought into play before an enemy might even think to detect it. When facing such masters of tradecraft, even the most disciplined of security guards, high-ranking military officers, or opposing agents might be forgiven for falling for the deceptions these master spies utilize in the hidden war.
INSERT INTO ref_sig_abilities (key, name, description, career_key, dataset_source, is_retired) VALUES ('UNMATCHEDVIGILANCE', 'Unmatched Vigilance', 'Once per game session at the beginning of a structured encounter, the character may spend 2 Destiny Points. If he does so, he determines the Initiative order of the first round of the encounter. Characters still make checks to determine Initiative, but these results will only apply after Unmatched Vigiliance''s effects end.', 'SENTINEL', 'respec', false) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('ALWAYSGETMYMARK', 'respec', 0, 0, 4, 'ALWAYSGETMYMARKBASIC', 'Always Get My Mark Base Ability', 'Once per game session, the character may choose a known minion NPC on the same planet to be her mark, spend 2 Destiny Points, and make a [B]Hard ([DI][DI][DI]) Streetwise check[b]. If she succeeds, the character tracks down the chosen mark; a new encounter begins as the character reaches the mark''s location. The exact nature of the encounter, as well as the circumstances under which it takes place, must be approved by the GM (see [B]Narrative Abilites[b] on page 40).', 30, false, true, false, false);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('ALWAYSGETMYMARK', 'respec', 1, 0, 1, 'ALWAYSGETMYMARKCHANGESKILL1', 'Change Skill: Underworld', 'May activate Always Get My Mark with Knowledge (Underworld) instead of Streetwise.', 10, true, true, false, false);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('ALWAYSGETMYMARK', 'respec', 1, 1, 1, 'ALWAYSGETMYMARKDESTINY', 'Destiny', 'Always Get My Mark costs 1 Destiny Point instead of 2.', 10, false, false, false, true);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('ALWAYSGETMYMARK', 'respec', 1, 2, 1, 'ALWAYSGETMYMARKINCREASEEFFECT1', 'Increase Effect: Rival', 'Upgrade the difficulty of the check once to find a rival NPC instead of a minion.', 10, true, true, true, true);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('ALWAYSGETMYMARK', 'respec', 1, 3, 1, 'ALWAYSGETMYMARKCHANGESKILL2', 'Change Skill: Survival', 'May activate Always Get My Mark with Survival instead of Streetwise.', 10, false, false, true, false);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('ALWAYSGETMYMARK', 'respec', 2, 0, 1, 'ALWAYSGETMYMARKREDUCEDIFFICULTY', 'Reduce Difficulty', 'Reduce the difficulty of the skill check to activate Always Get My Mark to [B]Average ([DI][DI])[b].', 15, true, false, false, true);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('ALWAYSGETMYMARK', 'respec', 2, 1, 1, 'ALWAYSGETMYMARKTAKEDOWN', 'Takedown', 'Upgrade the difficulty of the check once to begin with the mark in custody.', 15, false, false, true, false);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('ALWAYSGETMYMARK', 'respec', 2, 2, 1, 'ALWAYSGETMYMARKINCREASERANGE', 'Increase Range', 'If the character has a starship or access to interstellar travel, she may choose a character on a different planet to be her mark. If she does so, she travels to that mark''s world.', 15, true, false, false, true);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('ALWAYSGETMYMARK', 'respec', 2, 3, 1, 'ALWAYSGETMYMARKINCREASEEFFECT2', 'Increase Effect: Nemesis', 'Upgrade the difficulty of the check twice to find a nemesis NPC (or player character) instead of a minion.', 15, false, false, true, false);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('COUNTERESPIONAGE', 'respec', 0, 0, 4, 'COUNTERESPBASE', 'Counterespionage Base Ability', 'Once per game session, the character may spend two Destiny Points to make an [B]opposed Knowledge (Warfare) vs. Deception check[b] against an identified enemy agent or espionage leader. If successful, the character utterly foils one previously identified ploy or tactic associated with that enemy''s act of espionage. The exact nature of how this is accomplished (or was arranged earlier and revealed in a flashback) must be approved by the GM. Note that the identified enemy agent does not need to be physically present or near the character for this to happen, and the GM has the final say on exactly which NPCs are valid targets.', 30, false, true, false, false);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('COUNTERESPIONAGE', 'respec', 1, 0, 1, 'COUNTERESPBOOST', 'Add Boost', 'When making the skill check to activate Counterespionage, the character adds [BO] per Add Boost upgrade.', 10, true, false, false, false);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('COUNTERESPIONAGE', 'respec', 1, 1, 1, 'COUNTERESPSKILL1', 'Change Skill (Charm)', 'The skill check to activate Counterespionage can be performed using Charm instead of Knowledge (Warfare).', 10, true, true, false, false);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('COUNTERESPIONAGE', 'respec', 1, 2, 1, 'COUNTERESPREDUCESETBACK', 'Reduce Setback', 'Remove a [SE] from the character''s skill check as part of using Counterespionage.', 10, true, true, false, false);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('COUNTERESPIONAGE', 'respec', 1, 3, 1, 'COUNTERESPSKILL2', 'Change Skill (Negotiation)', 'The skill check to activate Counterespionage can be performed using Negotiation instead of Knowledge (Warfare).', 10, true, false, false, false);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('COUNTERESPIONAGE', 'respec', 2, 0, 1, 'COUNTERESPDESTINY', 'Destiny', 'To activate Counterespionage, the character needs to spend only one Destiny Point instead of the normal two.', 15, false, false, false, true);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('COUNTERESPIONAGE', 'respec', 2, 1, 1, 'COUNTERESPREDUCESETBACK', 'Reduce Setback', 'Remove a [SE] from the character''s skill check as part of using Counterespionage.', 15, true, false, true, true);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('COUNTERESPIONAGE', 'respec', 2, 2, 1, 'COUNTERESPBOOST', 'Add Boost', 'When making the skill check to activate Counterespionage, the character adds [BO] per Add Boost upgrade.', 15, true, false, true, true);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('COUNTERESPIONAGE', 'respec', 2, 3, 1, 'COUNTERESPTURNAGENT', 'Turn Agent', 'The character may spend a [TR] on a successful check to activate Counterespionage to turn one identified enemy espionage agent into a double agent secretly working for the character. Note that the identified enemy agent does not need to be physically present or near the character for this to happen, and that the GM has the final say on exactly which NPCs are valid targets.', 15, false, false, true, false);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('DEADLYREP', 'respec', 0, 0, 4, 'DEADLYREPBASE', 'Deadly Reputation Base Ability', 'Once per game session as an incidental, the character may spend 2 Destiny Points to activate Deadly Reputation. Until the end of the character''s next turn, increase the difficulty of all skill checks that target the character by one.', 30, false, false, false, false);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('DEADLYREP', 'respec', 1, 0, 1, 'DEADLYREPDURATION', 'Increase Duration', 'The effects of Deadly Reputation last for one additional turn per Increase Duration upgrade.', 10, false, false, false, true);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('DEADLYREP', 'respec', 1, 1, 1, 'DEADLYREPASSOCIATION', 'Deadly By Association', 'All effects of Deadly Reputation also apply to skill checks that target the character''s allies while the ability is in effect. This applies only to allies involved in the same encounter as the character, as determined by the Game Master.', 10, true, true, true, false);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('DEADLYREP', 'respec', 1, 2, 1, 'DEADLYREPADDSETBACK', 'Add Setback', 'Add a [SE] to skill checks targeting the character while Deadly Reputation is in effect per Add Setback upgrade.', 10, true, true, false, true);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('DEADLYREP', 'respec', 1, 3, 1, 'DEADLYREPDURATION', 'Increase Duration', 'The effects of Deadly Reputation last for one additional turn per Increase Duration upgrade.', 10, false, false, true, false);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('DEADLYREP', 'respec', 2, 0, 1, 'DEADLYREPINCREASEEFFECT', 'Increase Effect', 'Upgrade the difficulty of skill checks targeting the character once while Deadly Reputation is in effect. (This is in addition to increasing the difficulty per the effect of the base ability.)', 15, false, false, false, true);
