INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('FATDUEL', 'respec', 0, 0, 4, 'FATDUELBASIC', 'Fated Duel Basic Ability', 'Once per game session, during a combat encounter, the character may spend 2 Destiny Points and make a [B]Hard ([DI][DI][DI]) Discipline check[b] to challenge another character. If he succeeds, the two characters are locked in a duel for 3 rounds. For the duration of the duel, the two dueling characters can only make attacks targeting each other and no other characters can target the dueling characters with attacks (or otherwise intervene).', 30, false, false, false, false);
