INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('INSIGHTREVEL', 'respec', 0, 0, 4, 'INSIGHTFULBASIC', 'Insightful Revelation Basic Ability', 'Once per game session, the character may perform an Insightful Revelation action and spend 2 Destiny points to make a [B]Hard ([DI][DI][DI]) Knowledge (Education) check[b]. If he succeeds, he learns some valuable information that he did not previously possess pertaining to his current situation. What he learns is up to the GM. but it must be valuable to the player overcoming his immediate encounter or situation, and the information cannot be obtainable by any other immediately available means.', 30, false, false, false, false);
