INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('INVENTIVECREATION', 'respec', 0, 0, 4, 'INVENTIVECREATIONBASIC', 'Inventive Creation Base Ability', 'Once per game session, as an action, the character may spend 2 Destiny Points and make a [B]Daunting ([DI][DI][DI][DI]) Mechanics check[b]. If he succeeds, the character immediately uses available parts to build a device that functions as an item of his choice with a rarity of 5 or lower. The item is functional until the end of the encounter, at which point it falls apart, shorts out, or otherwise ceases to function permanently. The exact nature of the device the character its trying to construct as well as the end results, must be apporved by the GM (see [B]Narrative Abilities[b] on page 38).', 30, false, false, false, false);
