INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('LOS', 'respec', 0, 0, 4, 'LOSBASIC', 'Last One Standing Basic Ability', 'Once per game session during a combat encounter, the character may spend 2 Destiny Points to make a [B]Hard ([DI][DI][DI]) Resilience check[b]. If he succeeds, he skips his next turn and eliminates all enemy minions in the encounter. (The minions are all eliminated immediately, so will not get to participate further in the combat, but for the sake of the narrative, the PC can spend the next round of combat incapacitating them). The narrative means by which he accomplishes this is up to the player character, but should be suitably exciting, and must also be approved by the GM.', 30, false, false, false, false);
