INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('MUCHTOLEARN', 'respec', 2, 0, 1, 'MUCHTOLEARNCHANGESKILL1', 'Change Skill: Leadership', 'May make a Leadership check instead of a Knowledge (Education) check to activate Much to Learn.', 15, false, false, false, true);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('MUCHTOLEARN', 'respec', 2, 1, 1, 'MUCHTOLEARNCHANGESKILL2', 'Change Skill: Knowledge', 'May make an Knowledge skill check instead of a Knowledge (Education) check to activate Much to Learn.', 15, true, false, true, true);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('MUCHTOLEARN', 'respec', 2, 2, 1, 'MUCHTOLEARNIMPROVE', 'Improve Talent', 'If the character possesses the improved version of the chosen talent, allies affected count as possessing it too for the duration of the encounter.', 15, true, false, true, true);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('MUCHTOLEARN', 'respec', 2, 3, 1, 'MUCHTOLEARNSUPREME', 'Supreme Talent', 'If the character possesses the supreme version of the chosen talent, allies affected count as possessing it too for the duration of the encounter.', 15, false, false, true, false);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('MYCITY', 'respec', 0, 0, 4, 'MYCITYBASIC', 'My City Base Ability', 'Once per game session when in an urban setting, the character may spend 2 Destiny Points and make a [B]Hard ([DI][DI][DI]) Knowledge (Core Worlds)[b] or [B]Knowledge (Outer Rim) check[b]. If successful, for the remainder of the game session, the character may suffer 2 strain to recall or learn the location of any individual, group, or establishment within that city, and any relevant information.', 30, false, true, false, false);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('MYCITY', 'respec', 1, 0, 1, 'MYCITYBOOSTSKILL1', 'Boost Skill: Streetwise and Survival', 'When making a skill check while My City is active, the character adds [BO] to Streetwise and Survival checks.', 10, true, true, false, true);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('MYCITY', 'respec', 1, 1, 1, 'MYCITYREDUCEDIFFICULTY', 'Reduce Difficulty', 'The skill check difficulty to activate My City is [B]Average ([DI][DI])[b] instead of [B]Hard ([DI][DI][DI])[b].', 10, false, true, true, false);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('MYCITY', 'respec', 1, 2, 1, 'MYCITYCOVERUPGRADE', 'Cover Upgrade', 'While My City is active and the character is in the chosen city, whenever the character is in cover, he increases his ranged defense by 1.', 10, false, true, false, true);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('MYCITY', 'respec', 1, 3, 1, 'MYCITYBOOSTSKILL2', 'Boost Skill: Skulduggery and Stealth', 'When making a skill check while My City is active the character adds [BO] to Skulduggery and Stealth checks.', 10, true, true, true, false);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('MYCITY', 'respec', 2, 0, 1, 'MYCITYCHANGESKILL1', 'Change Skill: Streetwise', 'When activating My City, the character may make a Streetwise check instead of a Knowledge (Core Worlds/Outer Rim) check.', 15, true, false, false, true);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('MYCITY', 'respec', 2, 1, 1, 'MYCITYDESTINY', 'Destiny', 'To activate My City, the character only needs to spend 1 Destiny Point instead of the normal 2.', 15, true, false, true, true);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('MYCITY', 'respec', 2, 2, 1, 'MYCITYDOWNGRADE', 'Downgrade', 'While My City is active and the character is in the chosen city, he may suffer 2 strain to downgrade the difficulty of any Stealth check once.', 15, true, false, true, true);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('MYCITY', 'respec', 2, 3, 1, 'MYCITYCHANGESKILL2', 'Change Skill: Underworld', 'When activating My City, the character may make a Knowledge (Underworld) check instead of a Knowledge (Core Worlds/Outer Rim) check.', 15, true, false, true, false);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('NARROWESCAPE', 'respec', 0, 0, 4, 'NARROWESCAPEBASE', 'Narrow Escape Base Ability', 'Once per game session, the character may spend two Destiny Points to make a [B]Hard ([DI][DI][DI]) Streetwise check[b]. If successful, the character is immediately able to flee from the current personal-scale combat encounter unscathed. The challenge is not overcome or defeated, but the character is able to evade the hazard or threat for the time being. The exact nature of what the character is trying to accomplish, as well as the end results, must be approved by the GM (see [B]Narrative Abilities[b] on page 38), but should be suitably creative or daring.
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('NARROWESCAPE', 'respec', 1, 0, 1, 'REDUCESBNE', 'Reduce Setback', 'Remove [SE] from the Skill check to activate Narrow Escape.', 10, false, true, false, true);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('NARROWESCAPE', 'respec', 1, 1, 1, 'INCREASEEFFNE', 'Increase Effect', 'Affect an additional number of allied characters equal to Cunning per Increase Effect upgrade purchased.', 10, true, false, true, false);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('NARROWESCAPE', 'respec', 1, 2, 1, 'ADDBOOSTNE', 'Add Boost', 'Add [BO] to the skill check to activate Narrow Escape.', 10, true, true, false, true);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('NARROWESCAPE', 'respec', 1, 3, 1, 'CHANGESCALENE', 'Change Scale', 'Narrow Escape can be activated in a vehicle with the Piloting (Planetary) or Piloting (Space) skill.', 10, false, false, true, false);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('NARROWESCAPE', 'respec', 2, 0, 1, 'REDUCEDIFFNE', 'Reduce Difficulty', 'Reduce the difficulty of the skill check to activate Narrow Escape to [B]Average ([DI][DI])[b].', 15, true, false, false, true);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('NARROWESCAPE', 'respec', 2, 1, 1, 'INCREASEEFFNE', 'Increase Effect', 'Affect an additional number of allied characters equal to Cunning per Increase Effect upgrade purchased.', 15, false, false, true, true);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('NARROWESCAPE', 'respec', 2, 2, 1, 'CHANGESKILLNE', 'Change Skill', 'Narrow Escape can be activated during social encounters with the Deception skill.', 15, true, false, true, true);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('NARROWESCAPE', 'respec', 2, 3, 1, 'DESTINYNE', 'Destiny', 'Narrow Escape costs 1 Destiny Point instead of 2.', 15, false, false, true, false);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('PEERLESSINTERCEP', 'respec', 0, 0, 4, 'PEERLESSINTERCEPBASE', 'Peerless Interception Base Ability', 'Once per session as an out-of-turn incidental, the character may spend 2 Destiny Points to activate Peerless Interception. Until the end of the character''s second turn after activating Peerless Interception, when they use Parry or Reflect to reduce the damage of a hit, they reduce the damage by an additional amount equal to their current Force rating.', 30, false, false, false, false);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('PEERLESSINTERCEP', 'respec', 1, 0, 1, 'PEERLESSINTERCEPDESTINY', 'Destiny', 'Peerless Interception costs 1 fewer Destiny point to activate.', 10, false, false, false, true);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('PEERLESSINTERCEP', 'respec', 1, 1, 1, 'PEERLESSINTERCEPINCREASEDUR', 'Increase Duration', 'Peerless Interception lasts for one additional round.', 10, true, true, true, false);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('PEERLESSINTERCEP', 'respec', 1, 2, 1, 'PEERLESSINTERCEPINCREASEDUR', 'Increase Duration', 'Peerless Interception lasts for one additional round.', 10, true, false, false, true);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('PEERLESSINTERCEP', 'respec', 1, 3, 1, 'PEERLESSINTERCEPCRITCOUNT', 'Critical Counter', 'While Peerless Interception is active, when the character spends a despair result to inflict a hit on their attacker using Improved Parry or Improved Reflect, they may choose to also inflict a Critical Injury.', 10, false, true, true, false);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('PEERLESSINTERCEP', 'respec', 2, 0, 1, 'PEERLESSINTERCEPREDUCESTR', 'Reduce Strain', 'While Peerless Interception is active, the character only suffers strain to use Parry or Reflect the first time they use each talent during a round. Subsequent uses of Parry or Reflect during the same round do not require the character to suffer additional strain.', 15, false, false, false, true);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('PEERLESSINTERCEP', 'respec', 2, 1, 1, 'PEERLESSINTERCEPACTIVATEQUAL', 'Activate Quality', 'When the character uses Improved Parry or Improved Reflect to inflict a hit on an attacker while Peerless Interception is active, they may choose to activate one item quality of the attacker''s weapon (if using Reflect) or their own melee weapon (if using Parry). Apply the effects of the item quality as if the character had spent the minimum necessary [AD] to activate it as part of a combat check.', 15, true, false, true, true);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('PEERLESSINTERCEP', 'respec', 2, 2, 1, 'PEERLESSINTERCEPEFFORTCOUNT', 'Effortless Counter', 'Once per round when the character uses Parry or Reflect while Peerless Interception is active, they may use Improved Parry or Improved Reflect to inflict a hit on their attacker without spending a [TH] or [DE] result.', 15, false, false, true, true);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('PEERLESSINTERCEP', 'respec', 2, 3, 1, 'PEERLESSINTERCEPINCFREQU', 'Increase Frequency', 'The character may activate Peerless Interception one additional time per game session.', 15, true, false, true, false);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('PROPHECY', 'respec', 0, 0, 4, 'PROPHECYBASE', 'Base Power', 'Once per game session, the character may spend 1 Destiny Point and make a [B]Hard ([DI][DI][DI]) Vigilance check[b] to utter a prophecy. If they succeed on the check, they correctly foretell a single event that focuses around themselves They must describe the event in a brief summary. The GM can rule if the description is too involved; for example "I see myself sitting down at a table, and receiving a great fortune" is an acceptable prophecy, while "I see myself Sitting down at the sabacc table in the Misty Rancor Cantina and winning 1.2 million credits" is not.
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('PROPHECY', 'respec', 1, 0, 1, 'PROPHECYREDUCESETBACK', 'Reduce Setback', 'The character removes [SE] from the check to activate Prophecy.', 10, true, true, false, true);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('PROPHECY', 'respec', 1, 1, 1, 'PROPHECYFLOWOFUNIVERSE', 'Flow of the Universe', 'The character adds a [BO] to checks they make to attempt to bring the foretold event to fruition.', 10, true, true, true, true);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('PROPHECY', 'respec', 1, 2, 1, 'PROPHECYSHAREDREV', 'Shared Revelation', 'The prophecy may pertain to any one other character who hears it, instead of the character making the prophecy.', 10, true, true, true, true);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('PROPHECY', 'respec', 1, 3, 1, 'PROPHECYREDUCESETBACK', 'Reduce Setback', 'The character removes [SE] from the check to activate Prophecy.', 10, false, true, true, false);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('PROPHECY', 'respec', 2, 0, 1, 'PROPHECYRECUR', 'Recurrence', 'One additional time before the end of the game session, the character may spend 1 Destiny Point to have the prophecy''s foretold event recur, likely in a different form.', 15, true, false, false, true);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('PROPHECY', 'respec', 2, 1, 1, 'PROPHECYREDUCEDIFF', 'Reduce Difficulty', 'Reduce the difficulty of the skill check to activate Prophecy to Average.', 15, true, false, true, true);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('PROPHECY', 'respec', 2, 2, 1, 'PROPHECYDOOM', 'Doom', 'Add [SE] to any checks a character makes to prevent the foretold event from occurring.', 15, true, false, true, true);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('PROPHECY', 'respec', 2, 3, 1, 'PROPHECYDESTINY', 'Destiny', 'To activate Prophecy, the character does not have to spend a Destiny Point. They still must spend 1 Destiny Point to trigger the occurrence of the prophesied event.', 15, true, false, true, false);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('ROUSOR', 'respec', 0, 0, 4, 'ROUSORBASIC', 'Rousing Oratory Basic Ability', 'Once per game session, the character may perform a Rousing Oratory action, spend 2 Destiny Poins, and make a [B]Hard ([DI][DI][DI])[b] Leadership check to inspire a group to take action in a military situation about which  members were previously hesitant.', 30, false, false, false, false);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('ROUSOR', 'respec', 1, 0, 1, 'ROUSORCHANGESKILL', 'Change Skill: Discipline', 'May make a Discipline check instead of a Leadership check to activate Rousing Oratory.', 10, false, true, false, true);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('ROUSOR', 'respec', 1, 1, 1, 'ROUSORREDUCESETBACK', 'Reduce Setback', 'Remove [SE] from skill check to activate Rousing Oratory.', 10, true, true, true, true);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('ROUSOR', 'respec', 1, 2, 1, 'ROUSORRECOVERSTRAIN', 'Recover Strain', 'Friendly characters and NPCs targeted by Rousing Oratory recover a number of strain equal to the character''s ranks in Leadership.', 10, true, true, true, true);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('ROUSOR', 'respec', 1, 3, 1, 'ROUSORCHANGESKILL2', 'Change Skill: Cool', 'May make a Cool check instead of a Leadership check to activate Rousing Oratory.', 10, false, true, true, false);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('ROUSOR', 'respec', 2, 0, 1, 'ROUSORBOOSTALLIES', 'Boost Allies', 'After triggering Rousing Oratory, add [BO] per Boost Allies upgrade to all Discipline and Cool checks that other friendly characters and NPCs make until the end of the encounter.', 15, true, false, false, true);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('ROUSOR', 'respec', 2, 1, 1, 'ROUSORREDUCEDIFF', 'Reduce Difficulty', 'Reduce the difficulty of the skill check to activate Rousing Oratory to [B]Average ([DI][DI])[b].', 15, true, false, true, false);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('ROUSOR', 'respec', 2, 2, 1, 'ROUSORTURNINGPOINT', 'Turning Point', 'During a mass combat, may activate Rousing Oratory to create a turning point or boost allies already taking part in one.', 15, true, false, false, true);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('ROUSOR', 'respec', 2, 3, 1, 'ROUSORDESTINY', 'Destiny', 'Rousing Oratory costs 1 Destiny Point instead of 2.', 15, true, false, true, false);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('SHADOWLORD', 'respec', 0, 0, 4, 'SHADOWLORDBASE', 'Shadow Lord Base Ability', 'Once per session, the character may spend 2 Destiny Points and make a [B]Hard ([DI][DI][DI]) Streetwise check[b] to summon agents from an allied criminal syndicate. On success, an allied Minion group with a number of minions equal to 2 + [SU] appear as a group in the scene from a location of the Game Master''s choosing. They will work at the character''s direction and will assist on even the most dangerous of tasks.', 30, false, true, false, false);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('SHADOWLORD', 'respec', 1, 0, 1, 'CHANGESKILLCOER', 'Change Skill - Coercion', 'The skill check the character makes as part of using Shadow Lord can be made using Coercion instead of Streetwise.', 10, true, true, false, false);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('SHADOWLORD', 'respec', 1, 1, 1, 'REMSETBACKSHADOW', 'Remove Setback', 'Checks made by NPCs introduced by Shadow Lord remove [SE] per Remove Setback upgrade purchased.', 10, true, true, false, false);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('SHADOWLORD', 'respec', 1, 2, 1, 'CHANGESKILLSOCIETY', 'Change Skill - Knowledge (Underworld)', 'The skill check the character makes as part of using Shadow Lord can be made using Knowledge (Underworld) instead of Streetwise.', 10, true, true, false, false);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('SHADOWLORD', 'respec', 1, 3, 1, 'ADDBOOSTSHAD', 'Add Boost', 'Checks made by NPCs introduced by Shadow Lord add [BO] per Add Boost upgrade purchased.', 10, true, true, false, false);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('SHADOWLORD', 'respec', 2, 0, 1, 'ADDMINIONSSHAD', 'Additional Minions', 'An additional Minion group equal to the number of purchased Additional Minions upgrades appears in the scene to assist the character.', 15, true, false, false, true);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('SHADOWLORD', 'respec', 2, 1, 1, 'DESTSHADOW', 'Destiny', 'To activate Shadow Lord, the character needs to spend only one Destiny Point instead of the normal two Destiny Points.', 15, true, false, true, true);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('SHADOWLORD', 'respec', 2, 2, 1, 'DRAMENTRYSHADOW', 'Dramatic Entry', 'The characer may spend [TR] from a successful check to activate Shadow Lord to establish favorable or timely entry of the characters to the scene. The character may have the introduced NPCs act at the top of the next initiative round, after which their initiative is determined normally for the following rounds. Alternatively, the NPCs'' arrival could remove a foe''s resource or ally from the scene.', 15, true, false, true, false);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('SHADOWLORD', 'respec', 2, 3, 1, 'SUMRIVALSHADOW', 'Summon Rival', 'Also introduce an allied Rival per purchased Summon Rival upgrade to the scene to assist the character.', 15, true, false, false, false);
INSERT INTO ref_sig_ability_nodes (sig_ability_key, dataset_source, row_index, col_index, col_span, node_key, name, description, xp_cost, connect_up, connect_down, connect_left, connect_right) VALUES ('SUDDENDISC', 'respec', 0, 0, 4, 'SUDDISCBASIC', 'Sudden Discovery Basic Ability', 'Once per game session, the character may spend 2 Destiny Points to make a [B]Hard ([DI][DI][DI]) Knowledge (Outer Rim) or Knowledge (Core Worlds) check[b]. If he succeeds, the character can pinpoint his exact location without a map or other guide, discover a lost or hidden item or location, or identify a safe and fast path through any terrain. The exact nature of what the character is trying to accomplish, as well as the end results, must be approved by the GM.', 30, false, true, false, false);
